{
    "tests": [
        {
            "group": "Message.getGeneratedTSIG() after setTSIG with error and null querytsig",
            "cases": [
                {
                    "input": [],
                    "expected": "TSIGRecord whose error field equals the supplied error code and whose MAC field is null (because querytsig was null)",
                    "description": "Call setTSIG(TSIG key, int errorCode, null) on a Message. The generated TSIG record should store the provided error code while leaving the MAC undefined. getGeneratedTSIG() must return this record."
                }
            ]
        },
        {
            "group": "Message.getGeneratedTSIG() after setTSIG with error and non‑null querytsig",
            "cases": [
                {
                    "input": [],
                    "expected": "TSIGRecord whose error field equals the supplied error code and whose MAC field equals the MAC of the provided querytsig",
                    "description": "Create a TSIG key and a TSIGRecord queryTsig with a known MAC (e.g., byte[] {0x01,0x02}). Call setTSIG(key, errorCode, queryTsig). The generated TSIG must copy the MAC from queryTsig and the error code. getGeneratedTSIG() should return this record."
                }
            ]
        },
        {
            "group": "Message.getGeneratedTSIG() after consecutive setTSIG calls",
            "cases": [
                {
                    "input": [],
                    "expected": "TSIGRecord reflecting the parameters of the *last* setTSIG invocation (previous generatedTsig is overwritten)",
                    "description": "Invoke setTSIG(keyA) then setTSIG(keyB, error=5, null). The Message should keep only the TSIG generated by the second call. getGeneratedTSIG() must return a record that matches keyB and error=5, not the first one."
                },
                {
                    "input": [],
                    "expected": "null",
                    "description": "After the two calls above, invoke setTSIG(null). The generated TSIG should be cleared. getGeneratedTSIG() must return null."
                }
            ]
        },
        {
            "group": "Message.getGeneratedTSIG() after cloning a signed Message",
            "cases": [
                {
                    "input": [],
                    "expected": "TSIGRecord equal in content to the original Message's generatedTsig (key name, algorithm, MAC, error)",
                    "description": "Create a Message, call setTSIG(key, error=0, null) to generate a TSIG, then clone the Message via Message.clone(). The clone should retain the generated TSIG. getGeneratedTSIG() on the clone must return a TSIGRecord whose fields match those of the original."
                }
            ]
        },
        {
            "group": "Message.getGeneratedTSIG() after clearing TSIG following a successful setTSIG",
            "cases": [
                {
                    "input": [],
                    "expected": "null",
                    "description": "Call setTSIG(key) to create a generated TSIG, then call setTSIG(null) to clear it. getGeneratedTSIG() should return null, confirming that the clear operation overwrites the previous generatedTsig."
                }
            ]
        }
    ]
}
